import { execFile, spawn } from 'node:child_process'
import { existsSync, mkdtempSync, openSync, closeSync, readSync, rmSync, statSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { psQuote } from '@shared/utils/vps'

/*
 * Runs ONE script, generated by platforms/*.ts from validated values, with
 * administrator rights — never anything the window sends. One prompt per
 * action:
 *
 *   macOS    osascript "do shell script … with administrator privileges"
 *   Linux    pkexec (the desktop's polkit agent asks for the password)
 *   Windows  Start-Process -Verb RunAs (UAC)
 *
 * The script reads its inputs from a private work folder (0700) — the
 * password from a 0600 file it deletes as soon as it has read it, so it is
 * never on a command line — and writes progress lines (STEP / CHANGE / ERROR
 * / OK, see parseScriptLine) to progress.log there, which is followed here.
 *
 * On macOS and Linux the script text itself goes on the root shell's command
 * line (`sh -c`), so nothing on disk can be swapped between the prompt and
 * the run. Windows' UAC prompt can only start a file.
 */

export class ElevationError extends Error {
  constructor(
    message: string,
    readonly code: 'declined' | 'unavailable' | 'failed' | 'timeout'
  ) {
    super(message)
  }
}

export interface ElevatedRun {
  /** The script text: POSIX sh (macOS / Linux) or PowerShell (Windows). */
  script: string
  /** Files placed in the work folder before the run, e.g. { secret: password }. Mode 0600. */
  files?: Record<string, string>
  /** Shown in the macOS prompt. */
  prompt: string
  /** Every complete line the script writes to progress.log. */
  onLine: (line: string) => void
  timeoutMs?: number
}

const POLL_MS = 400

/** Follow a growing file, calling back with each complete line. */
const follow = (file: string, onLine: (line: string) => void) => {
  let offset = 0
  let partial = ''
  const read = () => {
    if (!existsSync(file)) return
    const size = statSync(file).size
    if (size <= offset) return
    const fd = openSync(file, 'r')
    try {
      const buffer = Buffer.alloc(size - offset)
      readSync(fd, buffer, 0, buffer.length, offset)
      offset = size
      const lines = (partial + buffer.toString('utf8')).split(/\r?\n/)
      partial = lines.pop() ?? ''
      for (const line of lines) if (line.trim()) onLine(line.trim())
    } finally {
      closeSync(fd)
    }
  }
  const timer = setInterval(read, POLL_MS)
  return {
    stop: () => {
      clearInterval(timer)
      read()
      if (partial.trim()) onLine(partial.trim())
    }
  }
}

/** Overwrite, then delete, the work folder (it held the password). */
const shred = (dir: string, files: string[]): void => {
  for (const name of files) {
    const path = join(dir, name)
    try {
      if (existsSync(path)) writeFileSync(path, Buffer.alloc(Math.max(64, statSync(path).size)))
    } catch {
      // Already deleted by the script.
    }
  }
  rmSync(dir, { recursive: true, force: true })
}

const launch = (scriptFile: string | null, script: string, dir: string, prompt: string, timeoutMs: number): Promise<{ code: number | null; stderr: string }> =>
  new Promise((resolve, reject) => {
    let child
    if (process.platform === 'darwin') {
      // argv items are passed to AppleScript as data, never parsed as code.
      child = execFile(
        '/usr/bin/osascript',
        [
          '-e',
          'on run argv',
          '-e',
          'do shell script "/bin/sh -c " & quoted form of (item 1 of argv) & " featured-vps " & quoted form of (item 2 of argv) with prompt (item 3 of argv) with administrator privileges',
          '-e',
          'end run',
          script,
          dir,
          prompt
        ],
        { timeout: timeoutMs, maxBuffer: 1024 * 1024 },
        (error, _stdout, stderr) => {
          if (!error) return resolve({ code: 0, stderr })
          const text = `${stderr}${error.message}`
          if (/-128|User canceled/i.test(text)) return reject(new ElevationError('The administrator prompt was cancelled.', 'declined'))
          if ((error as { killed?: boolean }).killed) return reject(new ElevationError('The setup took too long and was stopped.', 'timeout'))
          resolve({ code: typeof error.code === 'number' ? error.code : 1, stderr: text })
        }
      )
      return
    }
    if (process.platform === 'linux') {
      if (!['/usr/bin/pkexec', '/bin/pkexec'].some(existsSync)) {
        return reject(new ElevationError('pkexec (polkit) is needed to ask for the administrator password. Install the "pkexec" / "policykit-1" package.', 'unavailable'))
      }
      child = spawn('pkexec', ['/bin/sh', '-c', script, 'featured-vps', dir], { stdio: ['ignore', 'ignore', 'pipe'] })
    } else {
      // Windows: UAC can only start a program; the script is a file in the private work folder.
      const outer = `$p = Start-Process -FilePath powershell.exe -Verb RunAs -Wait -PassThru -WindowStyle Hidden -ArgumentList '-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-File',${psQuote(`"${scriptFile}"`)},'-WorkDir',${psQuote(`"${dir}"`)}; exit $p.ExitCode`
      child = spawn('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command', outer], { windowsHide: true, stdio: ['ignore', 'ignore', 'pipe'] })
    }
    let stderr = ''
    child.stderr?.on('data', (d: Buffer) => (stderr = (stderr + d.toString()).slice(-4000)))
    const timer = setTimeout(() => {
      child.kill()
      reject(new ElevationError('The setup took too long and was stopped.', 'timeout'))
    }, timeoutMs)
    child.on('error', error => {
      clearTimeout(timer)
      reject(new ElevationError(error.message, 'unavailable'))
    })
    child.on('exit', code => {
      clearTimeout(timer)
      if (process.platform === 'linux' && (code === 126 || code === 127)) {
        return reject(new ElevationError('The administrator password was not given (or no polkit agent is running).', 'declined'))
      }
      if (process.platform === 'win32' && /cancel/i.test(stderr)) return reject(new ElevationError('The administrator prompt was declined.', 'declined'))
      resolve({ code, stderr })
    })
  })

/** Run the script elevated; resolves with its exit code (0 = OK). Rejects only when it could not run. */
export const runElevated = async (run: ElevatedRun): Promise<{ code: number | null; stderr: string }> => {
  if (!['darwin', 'linux', 'win32'].includes(process.platform)) throw new ElevationError('Not supported on this system.', 'unavailable')
  const dir = mkdtempSync(join(tmpdir(), 'featured-vps-'))
  const names = Object.keys(run.files ?? {})
  try {
    for (const [name, content] of Object.entries(run.files ?? {})) {
      if (!/^[a-z]+$/.test(name)) throw new Error('Bad work file name.')
      writeFileSync(join(dir, name), content, { mode: 0o600 })
    }
    const progress = join(dir, 'progress.log')
    writeFileSync(progress, '', { mode: 0o600 })
    let scriptFile: string | null = null
    if (process.platform === 'win32') {
      scriptFile = join(dir, 'run.ps1')
      writeFileSync(scriptFile, run.script, { encoding: 'utf8', mode: 0o600 })
    }
    const follower = follow(progress, run.onLine)
    try {
      return await launch(scriptFile, run.script, dir, run.prompt, run.timeoutMs ?? 15 * 60_000)
    } finally {
      follower.stop()
    }
  } finally {
    shred(dir, names)
  }
}
